using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;
using Microsoft.Build.Framework;

var reader = new BinLogReader();
var records = new List<BuildEventArgs>();
reader.ReadRecords("/tmp/sv-374156a272dc4cba83176a6ffd6ad551/build.binlog")
    .ToList()
    .ForEach(r => records.Add(r.Args));

// Find the Api project errors specifically
var errors = records.OfType<BuildErrorEventArgs>().ToList();
Console.WriteLine("=== ALL ERRORS BY PROJECT ===\n");
foreach (var g in errors.GroupBy(e => e.ProjectFile))
{
    Console.WriteLine($"Project: {g.Key}");
    foreach (var e in g)
        Console.WriteLine($"  [{e.Code}] {e.File}({e.LineNumber},{e.ColumnNumber}): {e.Message}");
    Console.WriteLine();
}

// Check if Api had errors or was just cascading
var apiErrors = errors.Where(e => e.ProjectFile != null && e.ProjectFile.Contains("Api")).ToList();
Console.WriteLine($"Api project direct errors: {apiErrors.Count}");

// Check for MSB3202 or similar reference errors
var allMsgs = records.OfType<BuildMessageEventArgs>()
    .Where(m => m.ProjectFile != null && m.ProjectFile.Contains("Api") && m.Message != null && 
           (m.Message.Contains("error") || m.Message.Contains("Error") || m.Message.Contains("failed")))
    .Take(10).ToList();
foreach (var m in allMsgs)
    Console.WriteLine($"  Api msg: {m.Message?.Substring(0, Math.Min(200, m.Message.Length))}");
EOF

